package com.restaurant.management.service;
import com.restaurant.management.dto.*; import com.restaurant.management.enums.*; import com.restaurant.management.repository.TableauBordRepository; import com.restaurant.management.repository.TableRestaurantRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.time.LocalDate; import java.util.*;
@Service
public class TableauBordService {
 private final TableauBordRepository repository; private final TableRestaurantRepository tables; public TableauBordService(TableauBordRepository r,TableRestaurantRepository t){repository=r;tables=t;}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('TABLEAU_BORD_CONSULTER')")
 public TableauBordOperationsResponse operations(LocalDate debut,LocalDate fin){PeriodeTableauBord p=PeriodeTableauBord.creer(debut,fin);long disponibles=tables.countDisponibles(DisponibiliteTableSupport.COMMANDES_OCCUPANTES,DisponibiliteTableSupport.RESERVATIONS_OCCUPANTES,Instant.now());return new TableauBordOperationsResponse(p.debut(),p.fin(),repository.nombreCommandes(p.debutInstant(),p.finExclusive()),disponibles,completer(repository.commandesParEtat(p.debutInstant(),p.finExclusive()),StatutCommande.values()),repository.produitsVendus(p.debutInstant(),p.finExclusive()),completer(repository.reservations(p.debutInstant(),p.finExclusive()),StatutReservation.values()),repository.stocksFaibles());}
 @Transactional(readOnly=true) @PreAuthorize("hasAnyRole('ADMINISTRATEUR','GERANT') and hasAuthority('TABLEAU_BORD_FINANCIER_CONSULTER')")
 public TableauBordFinancierResponse finances(LocalDate debut,LocalDate fin){PeriodeTableauBord p=PeriodeTableauBord.creer(debut,fin);return new TableauBordFinancierResponse(p.debut(),p.fin(),repository.chiffreAffaires(p.debutInstant(),p.finExclusive()),completer(repository.paiementsParMode(p.debutInstant(),p.finExclusive()),ModePaiement.values()),repository.depensesAchat(p.debutInstant(),p.finExclusive()));}
 private List<IndicateurValeurResponse> completer(List<IndicateurValeurResponse> valeurs,Enum<?>[] enums){Map<String,BigDecimal> index=new HashMap<>();valeurs.forEach(v->index.put(v.libelle(),v.valeur()));return Arrays.stream(enums).map(e->new IndicateurValeurResponse(e.name(),index.getOrDefault(e.name(),BigDecimal.ZERO))).toList();}
}
